func worker(id int, wg *sync.WaitGroup) {
	defer wg.Done()
	for i := 0; i < 5; i++ {
		buf, err := pool.Alloc(1024)
		if err != nil {
			fmt.Printf("Worker %d: %v\n", id, err)
			continue
		}
		data := buf.Data()
		for j := range data {
			data[j] = byte(id + i)
		}
		fmt.Printf("Worker %d: allocated %d bytes\n", id, len(data))
		buf.Release()
		time.Sleep(time.Millisecond)
	}
}

func main() {
	var wg sync.WaitGroup
	for i := 0; i < 2; i++ {
		wg.Add(1)
		go worker(i, &wg)
	}
	wg.Wait()
}
